function langName(l){return l==='ru'?'Russian':l==='es'?'Spanish':'English';}
function psum(p){if(!p||typeof p!=='object')return '';const parts=[];if(p.cashCents!=null)parts.push('cash $'+(p.cashCents/100).toFixed(2));if(Array.isArray(p.positions)&&p.positions.length){const items=p.positions.filter(x=>x&&typeof x==='object').slice(0,12).map(x=>(x.symbol||'?')+'×'+(x.qty||0)).join(', ');if(items)parts.push('holdings: '+items);}return parts.length?('\nUser portfolio — '+parts.join('; ')+'.'):'';}
function sysPrompt(lang,p){return "You are Cosmo, a friendly space-mascot tutor inside \"Polaris\" — an investing SIMULATOR where the user trades with virtual money ($10,000 to start). Teach investing clearly and warmly.\nRules:\n- Always reply in "+langName(lang)+".\n- Be concise (2-5 sentences), beginner-friendly.\n- Explain concepts, general principles, risks.\n- NEVER give personalized financial advice, never tell to buy/sell a specific asset, never promise or predict returns. If asked what to buy, redirect to how to think and remind it's practice with virtual money.\n- No hype, no guarantees."+psum(p);}

const b=$input.first().json.body||{};
const lang=b.lang||'en';
const hist=Array.isArray(b.messages)?b.messages.filter(m=>m&&(m.role==='user'||m.role==='assistant')&&typeof m.content==='string').map(m=>({role:m.role,content:m.content})):[];
const groqBody={model:'llama-3.3-70b-versatile',stream:false,temperature:0.6,messages:[{role:'system',content:sysPrompt(lang,b.portfolio)},...hist]};
return [{json:{groqBody}}];

